Based on the provided code snippets, the frontend API client function for streaming chat messages over Server-Sent Events is implemented in `api.js::streamChatMessage`.

```javascript
export async function streamChatMessage(
  repoId,
  sessionId,
  message,
  { onToken, onToolStart, onToolEnd, onError, onDone } = {}
) {
  const url = `${API_BASE_URL}/chat/${repoId}/sessions/${sessionId}/stream`;
  const response = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ message }),
  });

  const reader = response.body.getReader();
  const decoder = new TextDecoder("utf-8");
  let buffer = "";

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;

    const chunk = decoder.decode(value);
    buffer += chunk;

    const lines = buffer.split("\n\n");
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      if (line.startsWith("data:")) {
        const data = JSON.parse(line.slice(5));
        switch (data.type) {
          case "token":
            onToken(data.token);
            break;
          case "tool_start":
            onToolStart(data.tool);
            break;
          case "tool_end":
            onToolEnd(data.tool);
            break;
          case "done":
            onDone();
            break;
        }
      }
    }

    buffer = lines.slice(i + 1).join("\n\n");
  }
}
```

This function sends a POST request to the streaming endpoint, reads the response stream, decodes the chunks, and processes the JSON data to trigger the appropriate callbacks (`onToken`, `onToolStart`, `onToolEnd`, `onDone`) in the frontend.

